/* @lc app=leetcode id=2076 lang=kotlin */
class Solution { fun friendRequests(n: Int, restrictions: Array<IntArray>, requests: Array<IntArray>): BooleanArray = IntArray(n) { it }.let { p -> kotlin.DeepRecursiveFunction<Int, Int> { i -> if (p[i] == i) i else callRecursive(p[i]).also { p[i] = it } }.let { f -> requests.map { q -> f.invoke(q[0]).let { r1 -> f.invoke(q[1]).let { r2 -> (r1 == r2 || restrictions.none { res -> f.invoke(res[0]).let { rr1 -> f.invoke(res[1]).let { rr2 -> (r1 == rr1 && r2 == rr2) || (r1 == rr2 && r2 == rr1) } } }).also { if (it && r1 != r2) p[r1] = r2 } } } }.toBooleanArray() } } }